slate 1 "Branch"

root: column
  none: empty title="Not a checkout" body="This thread's folder is not a git checkout." when={git.branch == null}
  head: row between when={git.branch != null}
    branch: text value={git.branch} mono strong
    changed: text value=`${plural(git.changed, 'file')} changed` muted
  counts: facts grid when={git.branch != null and !git.countsUnknown}
    - fact label="Ahead" value={git.ahead}
    - fact label="Behind" value={git.behind} tone={git.behind > 0 ? 'warning' : 'muted'}
    - fact label="Changed" value={git.changed}
  unknown: text value="Counts against upstream are not known yet." muted small when={git.branch != null and git.countsUnknown}
  read: text value=`read ${ago(git.readAt)}` muted small when={exists(git.readAt)}
  rebase: button label="Rebase onto upstream" primary when={git.branch != null and !git.countsUnknown and git.behind > 0}
    @press send text="This branch is behind upstream. Rebase it onto upstream and resolve any conflicts." with=[git.branch, git.ahead, git.behind]
